/* From Uiverse.io by WhiteNervosa - Tags: button */
.__UIV_SCOPE__ button {
  font-size: 18px;
  color: #e1e1e1;
  font-family: inherit;
  font-weight: 800;
  cursor: pointer;
  position: relative;
  border: none;
  background: none;
  text-transform: uppercase;
  transition-timing-function: cubic-bezier(0.25, 0.8, 0.25, 1);
  transition-duration: 400ms;
  transition-property: color;
}

.__UIV_SCOPE__ button:focus,
.__UIV_SCOPE__ button:hover {
  color: #fff;
}

.__UIV_SCOPE__ button:focus:after,
.__UIV_SCOPE__ button:hover:after {
  width: 100%;
  left: 0%;
}

.__UIV_SCOPE__ button:after {
  content: "";
  pointer-events: none;
  bottom: -2px;
  left: 50%;
  position: absolute;
  width: 0%;
  height: 2px;
  background-color: #fff;
  transition-timing-function: cubic-bezier(0.25, 0.8, 0.25, 1);
  transition-duration: 400ms;
  transition-property: width, left;
}
